"""Aspen Bridge 抽象基类。

定义所有 COM 交互的统一接口。WindowsBridge 实现真实 COM 调用，
StubBridge 提供纯内存模拟（开发/测试/搭建计划用）。
"""

from __future__ import annotations

from abc import ABC, abstractmethod
from typing import Any, Callable


class AspenBridge(ABC):
    """Aspen Plus 连接桥抽象。

    子类必须实现 call()、_app 属性、以及所有文件/引擎操作方法。
    """

    @abstractmethod
    def call(self, fn: Callable) -> Any:
        """在正确上下文执行 fn。Windows: COM 线程；Stub: 同步。"""
        ...

    @property
    @abstractmethod
    def _app(self) -> Any:
        """底层对象。Windows: win32com Dispatch；Stub: self。"""
        ...

    @abstractmethod
    def status(self) -> dict: ...
    @abstractmethod
    def probe(self) -> dict: ...
    @abstractmethod
    def open_file(self, path: str) -> None: ...
    @abstractmethod
    def close_file(self) -> None: ...
    @abstractmethod
    def save(self, path: str | None = None) -> None: ...
    @abstractmethod
    def generate_input_summary(self, file_path: str) -> None: ...
    @abstractmethod
    def run(self) -> None: ...
    @abstractmethod
    def run_async(self) -> None: ...
    @abstractmethod
    def reinit(self) -> None: ...
    @abstractmethod
    def reinit_and_run(self) -> None: ...
    @abstractmethod
    def stop(self) -> None: ...
    @abstractmethod
    def set_visible(self, show: bool) -> None: ...
    @abstractmethod
    def set_batch_refresh(self, off: bool) -> None: ...
    @abstractmethod
    def run_script(self, file_path: str) -> None: ...
    @abstractmethod
    def set_stream_param(self, stream_name: str, param: str, value: float,
                         basis: str | None = None) -> bool: ...
    @abstractmethod
    def set_stream_composition(self, stream_name: str, component: str,
                               flow: float) -> bool: ...
    @abstractmethod
    def set_stream_composition_batch(self, stream_name: str,
                                     components: dict, basis: str = "MOLE-FLOW",
                                     total_flow: float | None = None) -> str: ...
    @abstractmethod
    def get_value(self, *parts: str) -> Any: ...
    @abstractmethod
    def set_value(self, value: Any, *parts: str) -> bool: ...
    @abstractmethod
    def get_path_value(self, path: str) -> Any: ...
    @abstractmethod
    def set_path_value(self, path: str, value: Any, unit: str | None = None) -> str: ...
    @abstractmethod
    def get_node(self, *parts: str) -> Any: ...
    @abstractmethod
    def find_node(self, path: str) -> Any: ...
    @abstractmethod
    def root(self) -> Any: ...
    @abstractmethod
    def set_node_attribute(self, path: str, attribute: Any, value: Any) -> str: ...
    @abstractmethod
    def enumerate_children(self, node: Any) -> list: ...
    @abstractmethod
    def child_names(self, node: Any) -> list[str]: ...
    @abstractmethod
    def connect(self) -> None: ...
    @abstractmethod
    def disconnect(self) -> None: ...
